func normalizeEndpoint(endpoint string) (string, bool, error) {
    value := strings.TrimSpace(endpoint)
    if value == "" { return "", false, fmt.Errorf("endpoint must not be empty") }
    if !strings.Contains(value, "://") { value = "https://" + value }
    parsed, err := url.Parse(value)
    if err != nil { return "", false, fmt.Errorf("invalid endpoint: %w", err) }
    secure := parsed.Scheme == "https" || parsed.Scheme == "grpcs"
    if !secure && parsed.Scheme != "http" && parsed.Scheme != "grpc" {
        return "", false, fmt.Errorf("unsupported endpoint scheme: %s", parsed.Scheme)
    }
    if parsed.Host == "" || parsed.Path != "" && parsed.Path != "/" {
        return "", false, fmt.Errorf("endpoint must contain only an authority")
    }
    return parsed.Host, secure, nil
}

func validateCredentials(c Credentials, secure bool) error {
    if strings.TrimSpace(c.BearerToken) == "" && c.BearerToken != "" || strings.ContainsAny(c.BearerToken, "\r\n") {
        return fmt.Errorf("invalid bearer credential")
    }
    if c.BearerToken != "" && !secure { return fmt.Errorf("bearer credentials require a secure endpoint") }
    return nil
}

func unaryAuth(token string) grpc.UnaryClientInterceptor {
    return func(ctx context.Context, method string, req, reply any, cc *grpc.ClientConn, invoker grpc.UnaryInvoker, opts ...grpc.CallOption) error {
        if token != "" { ctx = metadata.AppendToOutgoingContext(ctx, "authorization", "Bearer "+token) }
        return invoker(ctx, method, req, reply, cc, opts...)
    }
}

func streamAuth(token string) grpc.StreamClientInterceptor {
    return func(ctx context.Context, desc *grpc.StreamDesc, cc *grpc.ClientConn, method string, streamer grpc.Streamer, opts ...grpc.CallOption) (grpc.ClientStream, error) {
        if token != "" { ctx = metadata.AppendToOutgoingContext(ctx, "authorization", "Bearer "+token) }
        return streamer(ctx, desc, cc, method, opts...)
    }
}

// NewClient selects secure gRPC by default. Use an explicit grpc:// endpoint
// only for a local plaintext server; callers never select build tags or
// platform feature flags.
func NewClient(ctx context.Context, endpoint string, c Credentials) (*Client, error) {
    target, secure, err := normalizeEndpoint(endpoint)
    if err != nil { return nil, err }
    if err := validateCredentials(c, secure); err != nil { return nil, err }
    var transportCredentials credentials.TransportCredentials
    if secure {
        config := &tls.Config{RootCAs: c.RootCAs, Certificates: nil, ServerName: c.ServerName, MinVersion: tls.VersionTLS13}
        if c.ClientCertificate != nil { config.Certificates = []tls.Certificate{*c.ClientCertificate} }
        transportCredentials = credentials.NewTLS(config)
    } else {
        transportCredentials = insecure.NewCredentials()
    }
    conn, err := grpc.DialContext(ctx, target,
        grpc.WithTransportCredentials(transportCredentials),
        grpc.WithUnaryInterceptor(unaryAuth(c.BearerToken)),
        grpc.WithStreamInterceptor(streamAuth(c.BearerToken)),
    )
    if err != nil { return nil, err }
    httpTLS := &tls.Config{RootCAs: c.RootCAs, ServerName: c.ServerName, MinVersion: tls.VersionTLS13}
    if c.ClientCertificate != nil { httpTLS.Certificates = []tls.Certificate{*c.ClientCertificate} }
	httpClient := &http.Client{
		Transport: &http.Transport{TLSClientConfig: httpTLS},
		CheckRedirect: func(_ *http.Request, _ []*http.Request) error { return http.ErrUseLastResponse },
	}
    return &Client{
        conn: conn,
        endpoint: func() string { scheme := "http://"; if secure { scheme = "https://" }; return scheme + target }(),
        secure: secure,
        bearerToken: c.BearerToken,
        httpClient: httpClient,
        transports: make(map[string]string),
        Actors: actorsv1.NewActorsServiceClient(conn),
        Stream: streamv2.NewStreamServiceClient(conn),
        Buckets: objectsv2.NewBucketsServiceClient(conn),
        Objects: objectsv2.NewObjectsServiceClient(conn),
        Multipart: objectsv2.NewMultipartServiceClient(conn),
        Workers: workersv1.NewWorkersServiceClient(conn),
        Filesystem: filesystemv2.NewFilesystemServiceClient(conn),
        Harness: harnessv2.NewHarnessServiceClient(conn),
        Inference: InferenceServices{
            Models: inferencev1.NewModelsServiceClient(conn),
            Contexts: inferencev1.NewContextsServiceClient(conn),
            WarmContexts: inferencev1.NewWarmContextsServiceClient(conn),
            Runs: inferencev1.NewRunsServiceClient(conn),
            Evaluations: inferencev1.NewEvaluationsServiceClient(conn),
        },
        Machines: machinesv1.NewMachinesServiceClient(conn),
    }, nil
}

